INSERT INTO `Page` (`id`, `slug`, `title`, `content`, `metaTitle`, `metaDesc`) VALUES ('page_1', 'about', 'About Zoqonyx Solution Hub', '### Our Mission\\n\\nZoqonyx Solution Hub is an open, high-performance web platform dedicated to delivering free, privacy-first digital utilities. Developed by Newix Tech Solutions, the platform empowers developers, designers, students, and digital creators worldwide.\\n\\n### Zero-Upload Browser Architecture\\n\\nTraditional online tools upload your confidential media, contracts, and source code to remote cloud servers. Zoqonyx overturns this paradigm by processing all files and calculations client-side using WebAssembly, HTML5 Canvas, and Web Workers. Your data never leaves your computer.\\n\\n### 100% Free & No Sign-Up Required\\n\\nEvery utility is completely free with zero subscription fees, no credit card requirements, and no mandatory login walls.', 'About Us – Free Client-Side Tools Mission | Zoqonyx', 'Learn about Zoqonyx Solution Hub, developed by Newix Tech Solutions to empower creators with free client-side digital tools.') ON DUPLICATE KEY UPDATE `content` = VALUES(`content`);
INSERT INTO `Page` (`id`, `slug`, `title`, `content`, `metaTitle`, `metaDesc`) VALUES ('page_2', 'privacy-policy', 'Privacy Policy', '### Absolute Data Confidentiality\\n\\nAt Zoqonyx Solution Hub, privacy is not an afterthought—it is our core architecture. When you compress an image, merge a PDF, generate a QR code, or inspect an SSL certificate, the computation executes locally on your device.\\n\\n### Zero File Storage\\n\\nWe do not operate backend file storage or telemetry for uploaded files. Once you refresh or close your browser tab, all temporary data in memory is permanently destroyed.\\n\\n### Local Analytics & Cookies\\n\\nWe use standard non-intrusive analytics solely to monitor aggregated traffic patterns. No personal identifiable information is ever monetized or shared with third parties.', 'Privacy Policy – Zero Data Retention Guarantee | Zoqonyx', 'Read our transparent privacy policy. All data processing occurs client-side in your browser with zero remote storage.') ON DUPLICATE KEY UPDATE `content` = VALUES(`content`);
INSERT INTO `Page` (`id`, `slug`, `title`, `content`, `metaTitle`, `metaDesc`) VALUES ('page_3', 'terms', 'Terms of Service', '### Acceptance of Terms\\n\\nBy accessing and utilizing Zoqonyx Solution Hub, you agree to be bound by these Terms of Service and all applicable local, national, and international laws.\\n\\n### Permitted Use\\n\\nOur utilities are provided free of charge for both personal and commercial use. You agree not to attempt to disrupt or overwhelm our infrastructure through automated denial-of-service attacks or malicious scraping.\\n\\n### Disclaimer of Warranties\\n\\nAll tools and calculations are provided on an "as is" basis. While we strive for absolute mathematical and technical accuracy, Zoqonyx Solution Hub disclaims all implied warranties of fitness for a particular purpose.', 'Terms of Service – Usage Guidelines | Zoqonyx', 'Review the terms and conditions governing the usage of Zoqonyx Solution Hub online tools and services.') ON DUPLICATE KEY UPDATE `content` = VALUES(`content`);
INSERT INTO `Tool` (`id`, `slug`, `name`, `description`, `category`, `isActive`, `isComingSoon`, `icon`, `order`, `metaTitle`, `metaDesc`, `content`, `usageCount`, `createdAt`, `updatedAt`) VALUES ('tool_1', 'image-compressor', 'Image Compressor', 'Compress JPG, PNG, and WebP images client-side with quality slider, before/after preview, and batch processing up to 50 files.', 'Image Tools', 1, 0, 'Minimize2', 1, 'Free Image Compressor Online (100% Free & Private) | Zoqonyx', 'Compress JPG, PNG, and WebP images client-side with quality slider, before/after preview, and batch processing up to 50 files. 100% free with zero registration. Processed safely in your browser.', '## Free Online Image Compressor\n\nCompress JPG, PNG, and WebP images client-side with quality slider, before/after preview, and batch processing up to 50 files.\n\n### Key Benefits\n- **100% Free**: No paywalls, daily quotas, or premium subscriptions.\n- **Zero Server Uploads**: Processed locally inside your browser for total confidentiality.\n- **Sub-Millisecond Speed**: Runs directly on your device CPU/GPU with no server latency.\n- **No Login Required**: Open the page and get results immediately.', 0, NOW(3), NOW(3)) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `content` = VALUES(`content`), `isActive` = VALUES(`isActive`), `isComingSoon` = VALUES(`isComingSoon`);
